    candidate: Candidate,
    before: os.stat_result,
    temporary: Path,
    digest: str,
    destination: Path,
    backup_root: Path,
    catalog: Catalog,
) -&gt; FileResult:
    if destination.exists():
        if destination.is_symlink() or not destination.is_file():
            raise OSError(f'destination is not a regular file: {destination}')
