            'relative_path': candidate.relative_path.as_posix(),
            'size': before.st_size,
            'mtime_ns': before.st_mtime_ns,
            'sha256': digest,
            'destination': destination.relative_to(backup_root).as_posix(),
            'copied_at_ns': time.time_ns(),
            'result': 'copied',
        }
    )
